#include <vector>
#include <unordered_map>

class Solution {
public:
    int numIdenticalPairs(std::vector<int>& nums) {
        std::unordered_map<int, int> counts;
        int ans = 0;
        for (int x : nums) {
            ans += counts[x]++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int numIdenticalPairs(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        int ans = 0;
        for (int x : nums) {
            int prev = counts.getOrDefault(x, 0);
            ans += prev;
            counts.put(x, prev + 1);
        }
        return ans;
    }
}

var numIdenticalPairs = function(nums) {
    const counts = new Map();
    let ans = 0;
    for (const x of nums) {
        const prev = counts.get(x) || 0;
        ans += prev;
        counts.set(x, prev + 1);
    }
    return ans;
};
